<?php declare(strict_types=1); ?>
<div class="container py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><p class="text-primary fw-semibold mb-1">Almacén</p><h1 class="h2">Pedidos para despacho</h1></div><a class="btn btn-outline-secondary" href="<?= htmlspecialchars($url->to('/almacen'), ENT_QUOTES, 'UTF-8') ?>">Volver</a></div>
<?php if ($orders === []): ?><section class="bento-card p-4"><p class="mb-0">No hay pedidos para despacho.</p></section><?php endif; ?>
<div class="row g-4"><?php foreach ($orders as $order): ?><div class="col-12"><section class="bento-card p-4"><div class="d-flex flex-wrap justify-content-between"><div><h2 class="h4"><?= htmlspecialchars($order['codigo_pedido'], ENT_QUOTES, 'UTF-8') ?></h2><p><?= htmlspecialchars($order['cliente'], ENT_QUOTES, 'UTF-8') ?> · Bs <?= number_format((float) $order['total'], 2) ?></p></div><span class="badge text-bg-info align-self-start"><?= htmlspecialchars($order['estado_envio'] ?? 'sin registrar', ENT_QUOTES, 'UTF-8') ?></span></div><form method="post" action="<?= htmlspecialchars($url->to('/almacen/envios/' . $order['id_venta']), ENT_QUOTES, 'UTF-8') ?>" class="row g-3"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><div class="col-md-4"><label class="form-label">Destinatario</label><input class="form-control" name="destinatario" required maxlength="150" value="<?= htmlspecialchars($order['destinatario'] ?? $order['cliente'], ENT_QUOTES, 'UTF-8') ?>"></div><div class="col-md-3"><label class="form-label">Teléfono</label><input class="form-control" name="telefono" maxlength="20" value="<?= htmlspecialchars($order['telefono'] ?? $order['cliente_telefono'] ?? '', ENT_QUOTES, 'UTF-8') ?>"></div><div class="col-md-5"><label class="form-label">Dirección</label><input class="form-control" name="direccion" required maxlength="255" value="<?= htmlspecialchars($order['direccion'] ?? '', ENT_QUOTES, 'UTF-8') ?>"></div><div class="col-md-3"><label class="form-label">Transportista</label><input class="form-control" name="transportista" maxlength="100" value="<?= htmlspecialchars($order['transportista'] ?? '', ENT_QUOTES, 'UTF-8') ?>"></div><div class="col-md-3"><label class="form-label">Guía</label><input class="form-control" name="numero_guia" maxlength="100" value="<?= htmlspecialchars($order['numero_guia'] ?? '', ENT_QUOTES, 'UTF-8') ?>"></div><div class="col-md-3"><label class="form-label">Estado</label><select class="form-select" name="estado"><?php foreach (['pendiente','preparando','despachado','entregado'] as $state): ?><option value="<?= $state ?>" <?= ($order['estado_envio'] ?? 'pendiente') === $state ? 'selected' : '' ?>><?= ucfirst($state) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Observación</label><input class="form-control" name="observacion" maxlength="500" value="<?= htmlspecialchars($order['observacion'] ?? '', ENT_QUOTES, 'UTF-8') ?>"></div><div class="col-12"><button class="btn btn-primary">Guardar envío</button></div></form></section></div><?php endforeach; ?></div></div>
